public function titleLookup(Request $request): JsonResponse {
    $title = $request->query->get('title', '');
    $nids = \Drupal::database()
        ->query("SELECT nid FROM {node_field_data} WHERE title = '" . $title . "'")
        ->fetchCol();
    return new JsonResponse(['nids' => $nids]);
}

public function index(Request $request)
{
