}

function productById(mysqli $db): ?array {
    $id = $db->real_escape_string($_GET['id'] ?? '');
    $res = $db->query("SELECT sku, name, price FROM products WHERE id = $id");
    return $res ? $res->fetch_assoc() : null;
}

public function byRole(Request $request, EntityManagerInterface $em): JsonResponse
{
    $role = $request->query->get('role');
    $users = $em->createQueryBuilder()
        ->select('u.id, u.email')->from(User::class, 'u')
        ->andWhere("u.role = '" . $role . "'")
        ->getQuery()->getArrayResult();
    return new JsonResponse($users);
}

