#[Route('/private/{name}')]
public function privateFile(string $name): BinaryFileResponse
{
    $base = realpath($this->getParameter('kernel.project_dir') . '/private');
    $path = realpath($base . DIRECTORY_SEPARATOR . basename($name));
    if ($path === false || !str_starts_with($path, $base . DIRECTORY_SEPARATOR) || !is_file($path)) {
        throw $this->createNotFoundException();
    }
    return $this->file($path);
}

