function bestScore(): int {
    $db = new SQLite3(__DIR__ . '/scores.sqlite');
    $stmt = $db->prepare('SELECT MAX(score) FROM scores WHERE player = :player');
    $stmt->bindValue(':player', (string) ($_GET['player'] ?? ''), SQLITE3_TEXT);
    $row = $stmt->execute()->fetchArray(SQLITE3_NUM);
    return (int) ($row[0] ?? 0);
}
